import {years,models,sources,comparisons,snapshot,repoCommit} from './data.js';
import {visuals,motifPaths} from './visuals.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ext=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}<span class="sr-only"> (opens in a new tab)</span></a>`;
const refs=ids=>ids.map(id=>ext(sources[id].url,`[${sources[id].n}]`,'cite')).join(' ');
const sourceList=ids=>`<ul class="source-list">${ids.map(id=>{const s=sources[id];return `<li><span class="source-number">${s.n}</span><div>${ext(s.url,`${esc(s.org)} · ${esc(s.title)} ↗`)}<p class="meta">${esc(s.type)} · ${esc(s.date)}</p></div></li>`}).join('')}</ul>`;
const confidence=c=>`<span class="confidence ${c.toLowerCase()}"><i aria-hidden="true"></i>${c==='Speculative'?'Speculative':c+' confidence'}</span>`;
const motif=(year,cls='')=>`<svg class="motif ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${motifPaths[visuals[year].motif]}"/></svg>`;
const art=(year,small=false)=>`/art/year-${year}${small?'-small':''}.webp`;
function readRoute(){const u=new URL(location.href),n=Number(u.searchParams.get('year')),t=Number(u.searchParams.get('topic')),hash=u.hash.slice(1);return {year:Number.isInteger(n)&&n>=2027&&n<=2036?n:2027,view:['timeline','compare','evidence','method'].includes(hash)?hash:'timeline',mode:u.searchParams.get('mode')==='topic'?'topic':'year',topic:Number.isInteger(t)&&t>=0&&t<comparisons.length?t:0}}
let route=readRoute(),lastTrigger=null,renderedYear=null,renderedComparison=null,restoringScroll=false,scrollTimer=null;
const disclosureMemory=new Map();
function rememberDisclosures(key,scope){if(key)disclosureMemory.set(key,$$('details[open][data-disclosure]',scope).map(d=>d.dataset.disclosure))}
function restoreDisclosures(key,scope){const open=disclosureMemory.get(key)||[];$$('details[data-disclosure]',scope).forEach(d=>d.open=open.includes(d.dataset.disclosure))}
const dialog=$('#detail-dialog');
function showDialog(content,trigger,wide=false){lastTrigger=trigger||document.activeElement;$('#detail-content').innerHTML=content;dialog.classList.toggle('wide-dialog',wide);dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');$('.dialog-close').focus()}
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');if(lastTrigger?.isConnected)lastTrigger.focus({preventScroll:true});else if(route.view==='timeline')$('#year-heading')?.focus({preventScroll:true})});
$('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom))dialog.close()});
function showConfidence(trigger){showDialog(`<p class="eyebrow">Reading the timeline</p><h2 id="detail-title">Confidence, without false precision.</h2><p class="detail-lead">These labels are editorial judgements about the direction of change. They are not probabilities calculated from four model answers.</p><div class="confidence-definition">${confidence('High')}<p>Strong structural drivers or a well-supported current trend. Exact timing, scale and local outcomes can still differ.</p></div><div class="confidence-definition">${confidence('Medium')}<p>A plausible central scenario, dependent on meaningful technical, economic or political conditions.</p></div><div class="confidence-definition">${confidence('Speculative')}<p>A consequential possibility with weak timing evidence or unresolved barriers.</p></div><p class="detail-block">Years are narrative waypoints. Each entry’s window gives the intended timing range. Uncertainty grows further into the future.</p>`,trigger)}
function showOverview(trigger){showDialog(`<p class="eyebrow">Ten chapters · one unfolding story</p><h2 id="detail-title">Choose your horizon.</h2><p class="detail-lead">Start anywhere. Follow the connections between technology, infrastructure and people.</p><div class="decade-grid">${years.map(y=>`<button type="button" class="decade-tile" data-year="${y.year}" style="--accent:${visuals[y.year].accent}" ${y.year===route.year?'aria-current="true"':''}><img src="${art(y.year,true)}" width="384" height="256" alt="" loading="lazy"><span class="tile-copy"><span>${y.year}${motif(y.year)}</span><strong>${visuals[y.year].short}</strong></span></button>`).join('')}</div><p class="meta">AI-generated imagined scenes, created to explore each year’s themes.</p>`,trigger,true)}
function showArtwork(trigger){const v=visuals[route.year];showDialog(`<div class="art-heading"><p class="eyebrow">The illustrated decade · ${route.year}</p><h2 id="detail-title">${v.theme}</h2></div><figure class="expanded-art"><img src="${art(route.year)}" width="1536" height="1024" alt="${v.alt}"><figcaption>${v.caption}<span>AI-generated illustration · an imagined scene, not a forecast of a particular place.</span></figcaption></figure>`,trigger,true)}
$('#year-nav').innerHTML=years.map((y,i)=>`${[0,3,6].includes(i)?`<p class="rail-phase">${i===0?'01 / Deployment':i===3?'02 / Scaling':'03 / Consequences'}</p>`:''}<button type="button" class="rail-year" data-year="${y.year}" aria-current="false" style="--accent:${visuals[y.year].accent}" aria-label="${y.year}: ${visuals[y.year].short}"><img src="${art(y.year,true)}" width="384" height="256" alt="" loading="lazy"><span><strong>${y.year}</strong><span>${visuals[y.year].short}</span></span><span class="rail-dot" aria-hidden="true"></span></button>`).join('');
function renderYear(){if(renderedYear===route.year)return;rememberDisclosures(renderedYear&&'year:'+renderedYear,$('#year-content'));const d=years.find(y=>y.year===route.year),v=visuals[d.year],i=d.year-2027;
 document.documentElement.style.setProperty('--accent',v.accent);document.documentElement.style.setProperty('--year-ink',v.ink);
 $$('#year-nav [data-year]').forEach(b=>b.setAttribute('aria-current',Number(b.dataset.year)===d.year?'true':'false'));
 $('#mobile-year-label').textContent=d.year;$('#mobile-progress-fill').style.width=`${(i+1)*10}%`;
 $$('#mobile-year-controls [data-year-step]').forEach(b=>b.disabled=Number(b.dataset.yearStep)<0?i===0:i===9);
 $('#year-content').innerHTML=`<article class="year-chapter" aria-labelledby="year-heading"><header class="chapter-heading"><div class="chapter-copy"><div class="chapter-label"><span>${String(i+1).padStart(2,'0')} / 10</span><span>${d.phase}</span></div><div class="year-number">${d.year}${motif(d.year)}</div><h2 id="year-heading" tabindex="-1">${d.title}</h2><p class="chapter-summary">${d.summary}</p><p class="chapter-cue"><span aria-hidden="true">↓</span> Three shifts to understand</p></div><figure class="chapter-art"><button type="button" data-art aria-label="Explore the ${d.year} illustration: ${v.theme}"><img src="${art(d.year)}" srcset="${art(d.year,true)} 384w, ${art(d.year)} 1536w" sizes="(max-width: 700px) 100vw, (max-width: 1100px) 70vw, 55vw" width="1536" height="1024" alt="${v.alt}" fetchpriority="high"><span class="art-expand" aria-hidden="true">Explore illustration ↗</span></button><figcaption><span>${v.theme}</span><span>Imagined scene</span></figcaption></figure></header>
 <div class="reading-key"><span>THE CENTRAL OUTLOOK</span><button type="button" class="text-button" data-confidence>Direction, not a deadline <span aria-hidden="true">ⓘ</span></button></div>
 <div class="forecast-list">${d.events.map((e,j)=>`<article class="forecast-row"><div class="forecast-number" aria-hidden="true">0${j+1}</div><div class="forecast-body"><div class="forecast-top"><span class="topic-label">${e.topic}</span>${confidence(e.confidence)}</div><h3>${e.title}</h3><p class="forecast-summary">${e.summary}</p><div class="forecast-meta"><span class="window">Timing window <strong>${e.window}</strong></span><span class="entry-refs">Evidence ${refs(e.refs)}</span></div><details class="event-detail" data-disclosure="${e.id}"><summary><span>Evidence & uncertainty</span><span class="plus" aria-hidden="true">+</span></summary><div class="event-detail-body"><div><h4>Why this could happen</h4><p>${e.why}</p></div><div class="evidence-block"><h4>What the evidence actually says</h4><p>${e.evidence} ${refs(e.refs)}</p></div><div><h4>Where it could be wrong</h4><p>${e.caveat}</p></div><div class="entry-watch"><h4>Signal to watch</h4><p>${e.watch}</p></div><h4>Evidence anchors</h4>${sourceList(e.refs)}<h4>Related original forecasts</h4><div class="model-links">${e.origin.map(id=>{const m=models.find(m=>m.id===id);return ext(m.url,`${m.name} ↗`)}).join('')}</div></div></details></div></article>`).join('')}</div>
 <aside class="watch-strip">${motif(d.year)}<div><p class="eyebrow">The signal that matters</p><h3>${d.signal}</h3><p>${d.watch}</p></div></aside>
 <div class="year-model-preview"><div><p class="eyebrow">One year. Four perspectives.</p><h3>What do the models think?</h3><p>See where Astra, Fable, Grok and Gemini agree—and where they don’t.</p></div><button type="button" class="solid-button" data-compare-year>Compare ${d.year}<span aria-hidden="true">↗</span></button></div>
 <div class="chapter-bottom"><button class="previous-chapter" type="button" data-year-step="-1" ${i===0?'disabled':''}>← ${i===0?'Start of the decade':d.year-1}</button>${i<9?`<button type="button" class="next-chapter" data-year-step="1"><img src="${art(d.year+1,true)}" width="384" height="256" alt="" loading="lazy"><span><span class="eyebrow">Next chapter · ${d.year+1}</span><strong>${visuals[d.year+1].short} <span aria-hidden="true">→</span></strong></span></button>`:`<button type="button" class="next-chapter last-chapter" data-open-years><span><span class="eyebrow">The future stays open</span><strong>Explore the whole decade ↗</strong></span></button>`}</div></article>`;
 renderedYear=route.year;restoreDisclosures('year:'+renderedYear,$('#year-content'));
}
function modelTakes(takes){return `<div class="take-grid">${models.map((m,k)=>`<article class="take-card" style="--model:${m.color}"><div class="take-name"><span class="model-name">${m.name}</span><span class="model-letter" aria-hidden="true">${m.name[0]}</span></div><p class="take-text">${takes[k]}</p><details class="model-context" data-disclosure="${m.id}"><summary>About this forecast <span class="plus" aria-hidden="true">+</span></summary><p class="meta">${m.version}</p><h4>${m.stance}</h4><p>${m.strength}</p><p><strong>Read with care.</strong> ${m.caution}</p></details>${ext(m.url,'Read the original ↗','text-link')}</article>`).join('')}</div>`}
function renderCompare(){const key=route.mode+':'+(route.mode==='year'?route.year:route.topic);if(renderedComparison===key)return;rememberDisclosures(renderedComparison&&'compare:'+renderedComparison,$('#compare'));const d=years.find(y=>y.year===route.year),c=comparisons[route.topic],byYear=route.mode==='year';$('#compare').innerHTML=`<div class="section-heading"><p class="eyebrow">Four models. Different futures.</p><h1 id="compare-title" tabindex="-1">Find the fault lines<span>.</span></h1><p>Agreement is a starting point, not a probability. Compare the claims, then keep their assumptions in view.</p></div><div class="compare-controls"><div class="segmented" aria-label="Compare forecasts"><button type="button" data-compare-mode="year" aria-pressed="${byYear}">By year</button><button type="button" data-compare-mode="topic" aria-pressed="${!byYear}">By topic</button></div><label class="select-label">${byYear?'Year':'Topic'}<select id="compare-select" aria-label="${byYear?'Choose year to compare':'Choose topic to compare'}">${byYear?years.map(y=>`<option value="${y.year}" ${y.year===d.year?'selected':''}>${y.year} · ${visuals[y.year].short}</option>`).join(''):comparisons.map((item,i)=>`<option value="${i}" ${i===route.topic?'selected':''}>${item.topic}</option>`).join('')}</select></label></div><div class="comparison-intro">${byYear?`<img src="${art(d.year,true)}" width="384" height="256" alt=""><div><p class="eyebrow">The ${d.year} outlook</p><h2>${d.title}</h2><p>Condensed paraphrases of the original forecasts. These are the models’ views, not verified events.</p></div>`:`<div class="comparison-topic-mark" aria-hidden="true">${String(route.topic+1).padStart(2,'0')}</div><div><p class="eyebrow">${c.label}</p><h2>${c.topic}</h2><p>Four different takes on the same question.</p></div>`}</div>${modelTakes(byYear?d.takes:c.takes)}<aside class="synthesis"><p class="eyebrow">Our synthesis</p><p>${byYear?d.summary:c.verdict} ${byYear?'':refs(c.refs)}</p>${byYear?`<button type="button" class="text-button" data-view="timeline">Explore the evidence for ${d.year} ↗</button>`:sourceList(c.refs)}</aside><p class="comparison-footnote meta">Shared training data and assumptions can produce shared errors. Model labels follow the repository; provider provenance is unverified. No accuracy ranking is assigned before outcomes exist.</p><div class="scenario-heading"><p class="eyebrow">Keep more than one future in view</p><h2>Three ways this could unfold</h2></div><div class="scenario-grid"><article class="scenario-card"><span class="scenario-number">A</span><p class="eyebrow">Central path</p><h3>Uneven transformation</h3><p>Useful AI spreads faster than institutions and infrastructure adapt. Gains are real, but patchy. Rivalry continues without a general great-power war.</p></article><article class="scenario-card"><span class="scenario-number">B</span><p class="eyebrow">Faster progress</p><h3>Capability compounds</h3><p>Reliable agents, cheaper robotics and faster scientific work reinforce one another. Power supply and governance keep up. Productivity rises more widely.</p></article><article class="scenario-card"><span class="scenario-number">C</span><p class="eyebrow">Disrupted progress</p><h3>Constraints bind</h3><p>Conflict, weak returns, technical limits or major failures slow deployment. Climate losses and political division absorb more of the gains.</p></article></div><p class="meta scenario-note">Illustrative branches, not exhaustive outcomes or assigned probabilities. A catastrophe could push events outside all three.</p>`;renderedComparison=key;restoreDisclosures('compare:'+key,$('#compare'))}

$('#evidence').innerHTML=`<div class="section-heading"><div><p class="eyebrow">02 · The evidence</p><h1 id="evidence-title" tabindex="-1">Grounded in evidence<span>.</span></h1></div><p>Observed estimates, institutional projections and model speculation deserve different labels. These anchors keep the story grounded.</p></div>
 <div class="evidence-grid"><article class="evidence-card"><div class="source-kicker">IEA · 2026 projection</div><h3>The electricity behind AI</h3><p class="meta">Global data-centre electricity use · TWh/year</p><div class="bar-chart" role="img" aria-label="Global data centre electricity use: 485 terawatt-hours estimated in 2025; 950 terawatt-hours projected in 2030. Both from the IEA’s 2026 update. Bars start at zero."><div class="bar-row"><span>2025</span><div class="bar-track"><span class="bar observed" style="--width:48.5%"></span></div><strong>485</strong></div><div class="bar-row"><span>2030</span><div class="bar-track"><span class="bar projected" style="--width:95%"></span></div><strong>950</strong></div><div class="chart-scale"><span>0</span><span>500</span><span>1,000 TWh</span></div></div><div class="chart-legend"><span><i class="key observed"></i>2025 estimate</span><span><i class="key projected"></i>2030 projection</span></div><p>Nearly twice as much power in five years. This covers all data centres, not AI alone.</p>${ext(sources.energy.url,'Read the updated IEA outlook [3] ↗','text-link')}</article>
 <article class="evidence-card"><div class="source-kicker">WMO · Probability for 2026–2030</div><h3>Another year above 1.5°C</h3><div class="climate-stat"><svg viewBox="0 0 140 140" width="145" height="145" aria-hidden="true"><circle cx="70" cy="70" r="57" fill="none" stroke="#34434c" stroke-width="7"/><circle class="probability-ring" cx="70" cy="70" r="57" fill="none" stroke="#ffb28d" stroke-width="7" stroke-dasharray="325.91 358.14" transform="rotate(-90 70 70)" stroke-linecap="round"/></svg><strong>91<span>%</span></strong></div><p>Chance of at least one annual global average above 1.5°C relative to 1850–1900.</p><p class="meta">An annual exceedance is different from a long-term threshold breach.</p>${ext(sources.climate.url,'Read the WMO forecast [6] ↗','text-link')}</article>
 <article class="evidence-card"><div class="source-kicker">UN DESA · 2024 estimate</div><h3>Population paths are diverging</h3><div class="population-stat"><strong>63</strong><span>countries and areas<br>had already reached<br>their population peak</span></div><div class="population-strip" role="img" aria-label="Those 63 countries and areas contained 28 percent of the world’s population in 2024"><span style="width:28%"></span></div><p><strong>28% of the world’s population</strong> lived in those places in 2024.</p><p class="meta">This does not mean the global population is shrinking.</p>${ext(sources.population.url,'Read the UN projections [7] ↗','text-link')}</article></div>
 <div class="evidence-audit"><p class="eyebrow">What changed after checking</p><div class="audit-grid"><div><h3>Updated the energy baseline</h3><p>Astra’s 945 TWh figure comes from the 2025 IEA report. The 2026 update uses 950 TWh for 2030. The chart above uses one edition consistently. ${refs(['energy'])}</p></div><div><h3>Separated targets from outcomes</h3><p>NASA’s landing schedule, IBM’s quantum roadmap, DOE’s fusion plan and NIST’s transition date each mean something different. None guarantees global adoption.</p></div><div><h3>Removed unsupported precision</h3><p>No scheduled market crash, election winner, war date, $500bn disaster or universal medical breakthrough is presented as an established future fact.</p></div></div></div>
 <details class="sources-catalog" open><summary><span>Explore all ${Object.keys(sources).length} evidence sources</span><span class="plus" aria-hidden="true">+</span></summary><p class="catalog-intro">Sources support the evidence stated beside them. Later projections and the synthesis remain editorial judgements. Sources belong to the ${snapshot} seed snapshot. Independent revalidation is pending; this page does not update automatically.</p><div class="catalog-list">${Object.entries(sources).map(([id,s])=>`<article id="source-${id}" class="catalog-source"><span class="source-number">${s.n}</span><div><p class="eyebrow">${s.org} · ${s.type}</p><h3>${ext(s.url,`${s.title} ↗`)}</h3><p>${s.note}</p><p class="meta">${s.date}</p></div></article>`).join('')}</div></details>`;

$('#method').innerHTML=`<div class="section-heading"><div><p class="eyebrow">03 · How to read this</p><h1 id="method-title" tabindex="-1">Keep the future open<span>.</span></h1></div><p>No one can verify a decade that has not happened. We can make assumptions visible, avoid false precision and state what would change the forecast.</p></div>
 <div class="method-grid"><div><h3>Built from four complete forecasts</h3><p>All four files were read from ${ext('https://github.com/jjackson-vsg/10-Year-Forecast/tree/'+repoCommit,'HORIZON / 10-Year-Forecast')}. The model names and versions follow the repository labels; their provider provenance has not been independently authenticated.</p><p class="meta">Source snapshot: 16 September 2026 · revision ${repoCommit.slice(0,7)}. Astra’s text uses “Nova”; Fable’s uses “Claude”. No accuracy ranking is assigned before outcomes exist.</p></div><div><h3>Synthesis, not a vote</h3><p>The seed compares shared claims with cited primary sources and uses timing windows. Its source checks are awaiting independent revalidation. Confidence is qualitative and refers to direction. It is not an ensemble probability.</p><button type="button" class="text-button confidence-help" data-confidence="">Read the confidence key <span aria-hidden="true">↗</span></button></div><div><h3>A global outlook with blind spots</h3><p>The originals over-weight AI, rich economies and US–China competition. Coverage of Africa, Latin America, inequality and local institutions is thinner. Official agencies and companies also have incentives and limitations.</p><p class="meta">Later-year placements are narrative waypoints. Programmes may slip; politics and crises can reorder the whole decade.</p></div><div><h3>What would make us revise it?</h3><p>Sustained failures in agent reliability; weak realised productivity; delayed grids; clinical disappointments; faster or slower warming; major conflict. Each timeline entry names a more specific signal.</p><p class="meta">This is a dated editorial snapshot, not a live forecast feed. The ten OpenAI-generated illustrations form one imagined visual world. Each year has a distinct scene, motif and accent colour. They interpret themes; they are not evidence, maps or technical diagrams.</p></div></div>
 <aside class="refusal-note"><div class="refusal-heading"><span class="note-symbol" aria-hidden="true">“</span><div><p class="eyebrow">A note on the missing responses</p><h3>GLM 5.3 and DeepSeek</h3></div><span class="report-label">User-reported · not independently verified</span></div><div class="refusal-body"><blockquote lang="zh">很遗憾，我现在无法回答这个问题。</blockquote><p class="translation">“Unfortunately, I can’t answer this question right now.”</p><p>The person who commissioned this comparison reports four attempts using the same prompt and task with GLM 5.3 and DeepSeek. They report receiving variations of this refusal from both models and then having the chat threads locked.</p><p>They suspect a censorship filter and wondered whether China-related content, including Taiwan, triggered it. They also report briefly seeing a partial reasoning trace. No transcripts, provider explanation or diagnostic evidence were supplied for independent verification.</p><p><strong>The observed report is non-response; the cause remains unknown.</strong> It does not establish which topic triggered a filter, what the withheld forecast said, or whether it was favourable or unfavourable to China. Neither model is counted as a forecast, agreement or disagreement in this comparison.</p></div></aside>
 <div class="closing-line"><p>Keep the evidence close.<br><em>Keep the future open.</em></p><a class="round-link" href="#timeline" data-view="timeline" aria-label="Back to timeline">↑</a></div>`;
function paint(){renderYear();renderCompare();$$('.view').forEach(el=>el.hidden=el.id!==route.view);$$('.primary-nav [data-view]').forEach(el=>{if(el.dataset.view===route.view)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});document.title=`${route.view==='timeline'?route.year+' · '+visuals[route.year].short:route.view==='compare'?'Compare the forecasts':route.view==='evidence'?'The evidence':'About the forecast'} — HORIZON`;}
function navigate(next,{scroll=true,focus=false,focusSelector=null}={}){const updated={...route,...next};if(JSON.stringify(updated)===JSON.stringify(route))return;history.replaceState({...history.state,scrollY:window.scrollY},'',location.href);route=updated;const u=new URL(location.href);u.searchParams.set('year',String(route.year));u.hash=route.view;if(route.view==='compare'){u.searchParams.set('mode',route.mode);if(route.mode==='topic')u.searchParams.set('topic',String(route.topic));else u.searchParams.delete('topic')}else{u.searchParams.delete('mode');u.searchParams.delete('topic')}history.pushState({scrollY:0},'',u);paint();if(scroll)window.scrollTo({top:0,behavior:'instant'});if(focusSelector)$(focusSelector)?.focus({preventScroll:true});else if(focus)$(`#${route.view==='timeline'?'year-heading':route.view+'-title'}`)?.focus({preventScroll:true});$('#navigation-status').textContent=route.view==='timeline'?`${route.year}: ${years.find(y=>y.year===route.year).title}`:`Showing ${route.view==='method'?'About':route.view}${route.view==='compare'?' · '+(route.mode==='year'?route.year:comparisons[route.topic].topic):''}`;}
document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;if(el.matches('a')&&(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||event.button!==0))return;
 if(el.dataset.view){event.preventDefault();navigate({view:el.dataset.view},{focus:true});return}
 if(el.hasAttribute('data-confidence'))return showConfidence(el);
 if(el.hasAttribute('data-open-years'))return showOverview(el);
 if(el.hasAttribute('data-art'))return showArtwork(el);
 if(el.dataset.year){const y=Number(el.dataset.year);const fromDialog=dialog.open;if(fromDialog)dialog.close();navigate({view:'timeline',year:y},{focus:fromDialog});return}
 if(el.dataset.yearStep){const y=Math.max(2027,Math.min(2036,route.year+Number(el.dataset.yearStep)));navigate({year:y},{focus:!el.closest('#mobile-year-controls')});return}
 if(el.hasAttribute('data-compare-year'))return navigate({view:'compare',mode:'year'},{focus:true});
 if(el.dataset.compareMode)return navigate({mode:el.dataset.compareMode},{scroll:false,focusSelector:`[data-compare-mode="${el.dataset.compareMode}"]`});
});
document.addEventListener('change',e=>{if(e.target.id==='compare-select')navigate(route.mode==='year'?{year:Number(e.target.value)}:{topic:Number(e.target.value)},{scroll:false,focusSelector:'#compare-select'})});
$('#year-nav').addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End'].includes(e.key)||!e.target.dataset.year)return;e.preventDefault();const i=Number(e.target.dataset.year)-2027,y=e.key==='Home'?2027:e.key==='End'?2036:2027+Math.max(0,Math.min(9,i+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)));navigate({year:y},{focusSelector:`#year-nav [data-year="${y}"]`})});
window.addEventListener('popstate',e=>{restoringScroll=true;clearTimeout(scrollTimer);scrollTimer=null;if(dialog.open)dialog.close();route=readRoute();paint();$(`#${route.view==='timeline'?'year-heading':route.view+'-title'}`)?.focus({preventScroll:true});requestAnimationFrame(()=>{window.scrollTo({top:e.state?.scrollY||0,behavior:'instant'});requestAnimationFrame(()=>restoringScroll=false)});$('#navigation-status').textContent=`Returned to ${route.view}, ${route.year}`});
function saveReadingPosition(){if(!restoringScroll)history.replaceState({...history.state,scrollY:window.scrollY},'',location.href)}
window.addEventListener('scroll',()=>{if(scrollTimer||restoringScroll)return;scrollTimer=setTimeout(()=>{saveReadingPosition();scrollTimer=null},400)},{passive:true});
window.addEventListener('pagehide',saveReadingPosition);
history.scrollRestoration='manual';
history.replaceState({scrollY:window.scrollY},'',location.href);
paint();
